/**
 * Exact signature geometry (spec §13, §19).
 *
 * The one rule the whole product hangs on: X and Y are NEVER scaled
 * independently. Every policy below computes a SINGLE scalar and applies it to
 * both axes. A signature that arrives 350x90 and is placed in a 400x150 field
 * must still look like the signature the person drew.
 */

export type FitPolicy = 'contain' | 'cover' | 'fit-width' | 'fit-height';
export type AlignPolicy = 'center' | 'baseline' | 'top-left';

export interface FitRequest {
  /** The field, owned by the integrating website. Authoritative. */
  fieldWidth: number;
  fieldHeight: number;
  /** The signature's intrinsic size (its SVG viewBox). */
  intrinsicWidth: number;
  intrinsicHeight: number;
  policy?: FitPolicy;
  align?: AlignPolicy;
}

export interface FitResult {
  /** The single scale factor applied to BOTH axes. */
  scale: number;
  width: number;
  height: number;
  offsetX: number;
  offsetY: number;
  /** True when the policy lets ink extend past the field (only `cover` does). */
  overflows: boolean;
}

export const DEFAULT_FIT_POLICY: FitPolicy = 'contain';

export class GeometryError extends Error {
  readonly code = 'INVALID_GEOMETRY';
}

/**
 * Compute placement of a signature inside a field.
 *
 * `contain` is the default and the only policy that guarantees the whole
 * signature is visible and undistorted.
 */
export function computeFit(request: FitRequest): FitResult {
  const { fieldWidth, fieldHeight, intrinsicWidth, intrinsicHeight } = request;
  const policy = request.policy ?? DEFAULT_FIT_POLICY;
  const align = request.align ?? 'center';

  for (const [name, value] of Object.entries({
    fieldWidth,
    fieldHeight,
    intrinsicWidth,
    intrinsicHeight,
  })) {
    if (!Number.isFinite(value) || value <= 0) {
      throw new GeometryError(`${name} must be a positive finite number`);
    }
  }

  const scaleX = fieldWidth / intrinsicWidth;
  const scaleY = fieldHeight / intrinsicHeight;

  let scale: number;
  switch (policy) {
    case 'contain':
      scale = Math.min(scaleX, scaleY);
      break;
    case 'cover':
      scale = Math.max(scaleX, scaleY);
      break;
    case 'fit-width':
      scale = scaleX;
      break;
    case 'fit-height':
      scale = scaleY;
      break;
    default: {
      // Exhaustiveness guard: an unknown policy must never silently fall back to
      // stretching, which is the exact failure mode this module exists to prevent.
      const exhaustive: never = policy;
      throw new GeometryError(`unknown fit policy: ${String(exhaustive)}`);
    }
  }

  const width = intrinsicWidth * scale;
  const height = intrinsicHeight * scale;

  let offsetX: number;
  let offsetY: number;
  switch (align) {
    case 'top-left':
      offsetX = 0;
      offsetY = 0;
      break;
    case 'baseline':
      // Sit the ink on the field's bottom edge — how a signature rests on a
      // printed line — while still centring horizontally.
      offsetX = (fieldWidth - width) / 2;
      offsetY = fieldHeight - height;
      break;
    case 'center':
    default:
      offsetX = (fieldWidth - width) / 2;
      offsetY = (fieldHeight - height) / 2;
      break;
  }

  return {
    scale,
    width,
    height,
    offsetX,
    offsetY,
    overflows: width > fieldWidth + 1e-9 || height > fieldHeight + 1e-9,
  };
}

/**
 * CSS equivalent of the same maths, for the SDK's `<img>`.
 *
 * The browser's own `object-fit` implementation is used rather than manual pixel
 * sizing: it is subpixel-accurate, survives zoom and font scaling, and does not
 * need a resize listener. `computeFit` remains the reference implementation that
 * the deterministic tests assert against.
 */
export function fitToCss(policy: FitPolicy = DEFAULT_FIT_POLICY, align: AlignPolicy = 'center') {
  const objectFit = policy === 'cover' ? 'cover' : 'contain';

  // fit-width / fit-height are `contain` plus a deliberate overflow allowance;
  // `contain` alone would shrink to the *other* axis and violate the policy.
  const width = policy === 'fit-width' ? '100%' : policy === 'fit-height' ? 'auto' : '100%';
  const height = policy === 'fit-height' ? '100%' : policy === 'fit-width' ? 'auto' : '100%';

  const objectPosition = align === 'baseline' ? 'center bottom' : align === 'top-left' ? 'left top' : 'center center';

  return { objectFit, objectPosition, width, height } as const;
}

/**
 * Verify a rendered box preserved the signature's aspect ratio.
 *
 * Used by the deterministic rendering tests (spec §43) with an explicit numeric
 * tolerance, because floating point and CSS subpixel rounding make exact equality
 * a test that fails for the wrong reasons.
 */
export function aspectRatioPreserved(
  intrinsicWidth: number,
  intrinsicHeight: number,
  renderedWidth: number,
  renderedHeight: number,
  tolerance = 1e-6,
): boolean {
  const expected = intrinsicWidth / intrinsicHeight;
  const actual = renderedWidth / renderedHeight;
  return Math.abs(expected - actual) <= tolerance * Math.max(1, expected);
}
