import { isNewerEvent, type TransactionEvent } from '@signdo/core';

export interface TransportOptions {
  apiBase: string;
  transactionId: string;
  channelToken: string;
  onEvent: (event: TransactionEvent) => void;
  onError?: (error: Error) => void;
}

/**
 * Server -> browser transport.
 *
 * SSE first, with automatic polling fallback. Both paths feed the same handler
 * and both are filtered by sequence, so a client that flaps between them cannot
 * apply an event twice or apply an old one after a new one (spec §20, §21).
 */
export class Transport {
  private source: EventSource | null = null;
  private pollTimer: number | null = null;
  private lastSequence = 0;
  private attempt = 0;
  private closed = false;

  constructor(private readonly options: TransportOptions) {}

  start(): void {
    this.closed = false;
    this.connect();
  }

  private url(path: string): string {
    const base = this.options.apiBase.replace(/\/$/, '');
    const separator = path.includes('?') ? '&' : '?';
    // EventSource cannot set headers, so the channel token travels as a query
    // parameter. It is single-transaction scoped and short-lived, and the server
    // redacts it from logs.
    return `${base}${path}${separator}channelToken=${encodeURIComponent(this.options.channelToken)}`;
  }

  private connect(): void {
    if (this.closed) return;

    try {
      const source = new EventSource(this.url(`/v1/signature-transactions/${this.options.transactionId}/events`));
      this.source = source;

      source.onopen = () => {
        this.attempt = 0;
        this.stopPolling(); // SSE is live; the fallback is no longer needed.
      };

      source.onmessage = (message) => this.handle(message.data);
      // Named events arrive on their own listeners, not onmessage.
      for (const type of [
        'transaction.snapshot',
        'transaction.scanned',
        'transaction.signing_started',
        'transaction.signed',
        'transaction.delivered',
        'transaction.confirmed',
        'transaction.expired',
        'transaction.cancelled',
        'transaction.failed',
      ]) {
        source.addEventListener(type, (event) => this.handle((event as MessageEvent).data));
      }

      source.addEventListener('overloaded', () => {
        // Server is at its stream cap. Polling keeps the flow working instead of
        // failing the signature outright.
        source.close();
        this.startPolling();
      });

      source.onerror = () => {
        source.close();
        this.source = null;
        if (this.closed) return;
        // Poll while reconnecting so a long outage does not stall the signature.
        this.startPolling();
        this.attempt += 1;
        // Exponential backoff with jitter — without jitter, every client that
        // dropped during an outage reconnects in lockstep and re-creates it.
        const delay = Math.min(30_000, 500 * 2 ** this.attempt) * (0.5 + Math.random() / 2);
        window.setTimeout(() => this.connect(), delay);
      };
    } catch (error) {
      this.options.onError?.(error as Error);
      this.startPolling();
    }
  }

  private handle(raw: string): void {
    let event: TransactionEvent;
    try {
      event = JSON.parse(raw) as TransactionEvent;
    } catch {
      return;
    }
    if (!isNewerEvent(this.lastSequence, event)) return; // stale or duplicate
    this.lastSequence = event.sequence;
    this.options.onEvent(event);
  }

  private startPolling(): void {
    if (this.pollTimer !== null || this.closed) return;
    this.pollTimer = window.setInterval(async () => {
      try {
        const response = await fetch(this.url(`/v1/signature-transactions/${this.options.transactionId}/status`));
        if (!response.ok) return;
        const status = await response.json();
        this.handle(
          JSON.stringify({
            eventId: 'poll',
            transactionId: this.options.transactionId,
            sequence: status.sequence,
            type: `transaction.${status.status.toLowerCase()}`,
            timestamp: new Date().toISOString(),
            status: status.status,
          }),
        );
      } catch {
        // Network blips are expected; the next tick retries.
      }
    }, 2000);
  }

  private stopPolling(): void {
    if (this.pollTimer !== null) {
      window.clearInterval(this.pollTimer);
      this.pollTimer = null;
    }
  }

  close(): void {
    this.closed = true;
    this.stopPolling();
    this.source?.close();
    this.source = null;
  }
}
