import type { TransactionStatus } from './stateMachine.ts';

export const EVENT_TYPES = [
  'transaction.created',
  'transaction.scanned',
  'transaction.signing_started',
  'transaction.signed',
  'transaction.delivered',
  'transaction.confirmed',
  'transaction.expired',
  'transaction.cancelled',
  'transaction.failed',
] as const;

export type EventType = (typeof EVENT_TYPES)[number];

export interface TransactionEvent {
  eventId: string;
  transactionId: string;
  /** Monotonic per transaction, starting at 1. Drives SSE replay and stale-event rejection. */
  sequence: number;
  type: EventType;
  timestamp: string;
  status: TransactionStatus;
  /** Present from `transaction.signed` onward. */
  signatureHash?: string;
}

const STATUS_EVENT: Partial<Record<TransactionStatus, EventType>> = {
  CREATED: 'transaction.created',
  SCANNED: 'transaction.scanned',
  SIGNING: 'transaction.signing_started',
  SIGNED: 'transaction.signed',
  DELIVERED: 'transaction.delivered',
  CONFIRMED: 'transaction.confirmed',
  EXPIRED: 'transaction.expired',
  CANCELLED: 'transaction.cancelled',
  FAILED: 'transaction.failed',
};

export function eventTypeForStatus(status: TransactionStatus): EventType | null {
  return STATUS_EVENT[status] ?? null;
}

/**
 * Stale/reordered event guard (spec §20).
 *
 * SSE reconnects replay from `Last-Event-ID`, and a slow network can deliver an
 * older event after a newer one. Consumers apply this before touching any state:
 * sequence numbers are the only ordering we trust, never arrival order.
 */
export function isNewerEvent(lastAppliedSequence: number, incoming: TransactionEvent): boolean {
  return incoming.sequence > lastAppliedSequence;
}
